<?php
define('PAGE_TITLE','Draft Question Bank Review');require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/system.php';requireAuth();if(!isHOD()&&!isCOE()) {header('Location: ../teaching/dashboard.php?error=access_denied');exit;}require_once __DIR__.'/../../includes/header.php';$reviewRole=isCOE()?'COE':'HOD';?>
<main class="max-w-7xl mx-auto w-full px-4 py-6 space-y-5"><div><p class="text-sm font-semibold text-indigo-600"><?=$reviewRole?> REVIEW</p><h1 class="text-2xl md:text-3xl font-bold">Question Bank Review Queue</h1><p class="text-slate-600 mt-1">Review questions individually, mark them verified or request corrections with remarks. A bank can advance only when every question is verified.</p></div><div id="queue" class="space-y-4"><div class="bg-white border rounded-xl p-5">Loading review queue…</div></div></main>
<script>
const api='../../api/review_drafts.php';const role=<?=json_encode($reviewRole)?>;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function call(action,values={}){const f=new FormData();f.set('action',action);Object.entries(values).forEach(([k,v])=>f.set(k,v));const r=await fetch(api,{method:'POST',body:f,credentials:'same-origin'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Request failed');return j.data||{};}
function draw(data){const root=document.getElementById('queue');const drafts=data.drafts||[];if(!drafts.length){root.innerHTML='<div class="bg-white border rounded-xl p-8 text-center text-slate-500">No question banks are waiting for your review.</div>';return;}root.innerHTML=drafts.map(d=>`<section class="bg-white border rounded-2xl p-5 shadow-sm"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-lg font-bold">${esc(d.paper_code)} — ${esc(d.course_title)}</h2><p class="text-sm text-slate-600">Staff ${esc(d.staff_code)} · ${esc(d.dept_name||d.dept_code)} · ${esc(d.semester)} · ${esc(d.academic_year)} · ${esc(d.exam_type)}</p></div><span class="h-fit rounded-full bg-indigo-50 text-indigo-700 px-3 py-1 text-sm">${d.questions.length} questions</span></div><div class="mt-4 space-y-3">${d.questions.map(q=>`<article class="border rounded-xl p-4" data-question="${q.id}"><div class="flex flex-wrap gap-2 text-xs mb-2"><span class="rounded bg-slate-100 px-2 py-1">${esc(q.section_type)}</span><span class="rounded bg-slate-100 px-2 py-1">${esc(q.question_type)}</span><span class="rounded bg-slate-100 px-2 py-1">${esc(q.marks)} mark(s)</span><span class="rounded bg-slate-100 px-2 py-1">Unit ${esc(q.unit_no)}.${esc(q.sub_unit)}</span><span class="rounded bg-emerald-50 text-emerald-700 px-2 py-1">${esc(q.k_level)} / ${esc(q.co_level)}</span><span class="rounded bg-slate-100 px-2 py-1">${esc(q.review_status||'PENDING')}</span></div><p class="whitespace-pre-wrap">${esc(q.question_text)}</p>${q.options_json?`<p class="text-sm mt-2"><b>Options:</b> ${esc(q.options_json)}</p>`:''}${q.match_column_a?`<p class="text-sm mt-2"><b>Match A:</b> ${esc(q.match_column_a)} <b>Match B:</b> ${esc(q.match_column_b)}</p>`:''}${q.image_path?`<img class="mt-3 max-h-64 rounded border" alt="Question diagram" src="../../api/draft_diagram.php?draft_id=${encodeURIComponent(d.id)}&question_id=${encodeURIComponent(q.id)}">`:''}<div class="mt-3 grid md:grid-cols-[1fr_auto_auto] gap-2"><input class="review-remarks rounded-lg border-slate-300" placeholder="Remarks required if correction is needed" value="${esc(q.review_remarks||'')}"><button class="verify rounded-lg bg-emerald-600 text-white px-3 py-2" data-draft="${d.id}" data-id="${q.id}">Mark verified</button><button class="correct rounded-lg bg-amber-100 text-amber-900 px-3 py-2" data-draft="${d.id}" data-id="${q.id}">Request correction</button></div></article>`).join('')}</div><div class="mt-4 flex flex-wrap gap-2 justify-end"><input class="bank-remarks rounded-lg border-slate-300 px-3 py-2" placeholder="Optional bank-level approval note"><button class="return-bank rounded-xl border border-rose-200 text-rose-700 px-4 py-2" data-id="${d.id}">Return entire bank</button><button class="approve-bank rounded-xl bg-indigo-600 text-white px-4 py-2" data-id="${d.id}">${role==='HOD'?'Approve & send to COE':'Approve & publish bank'}</button></div></section>`).join('');root.querySelectorAll('.verify').forEach(b=>b.onclick=()=>reviewQuestion(b,'VERIFIED'));root.querySelectorAll('.correct').forEach(b=>b.onclick=()=>reviewQuestion(b,'CORRECTION_REQUIRED'));root.querySelectorAll('.return-bank').forEach(b=>b.onclick=()=>returnBank(b));root.querySelectorAll('.approve-bank').forEach(b=>b.onclick=()=>approveBank(b));}
async function reload(){try{draw(await call('list'));}catch(e){document.getElementById('queue').innerHTML=`<div class="rounded-xl border border-rose-200 bg-rose-50 p-4 text-rose-800">${esc(e.message)}</div>`;}}
async function reviewQuestion(btn,decision){const a=btn.closest('article');const remarks=a.querySelector('.review-remarks').value;try{await call('review_question',{draft_id:btn.dataset.draft,question_id:btn.dataset.id,decision,remarks});await reload();}catch(e){Swal.fire('Could not save review',e.message,'error');}}
async function returnBank(btn){const sec=btn.closest('section');const remarks=sec.querySelector('.bank-remarks').value;if(!remarks.trim()){Swal.fire('Remarks required','Please explain what must be corrected.','warning');return;}const c=await Swal.fire({title:'Return this bank?',text:'The staff member will need to correct and resubmit it.',icon:'warning',showCancelButton:true,confirmButtonText:'Return'});if(!c.isConfirmed)return;try{await call('return_bank',{draft_id:btn.dataset.id,remarks});await reload();}catch(e){Swal.fire('Failed',e.message,'error');}}
async function approveBank(btn){const sec=btn.closest('section');const remarks=sec.querySelector('.bank-remarks').value;const c=await Swal.fire({title:role==='HOD'?'Send bank to COE?':'Approve final question bank?',text:role==='COE'?'Questions will be promoted to the approved question bank and temporary draft-question rows cleared.':'Every question must be verified first.',icon:'question',showCancelButton:true,confirmButtonText:'Continue'});if(!c.isConfirmed)return;try{const d=await call('approve_bank',{draft_id:btn.dataset.id,remarks});await Swal.fire('Success',d.message||'Approval saved.','success');await reload();}catch(e){Swal.fire('Cannot approve',e.message,'error');}}
reload();
</script><?php require_once __DIR__.'/../../includes/footer.php'; ?>
